data.value:
        double totalVleftaPaTvshPerArtMeTvsh = 0;
        double totalVleftaPaTvshPerArtPaTvsh = 0;
        double furnizimeTeTatueshme = 0;
        double furnizimeTePaTatueshme = 0;
        double totaliPaTVSH = 0;
        double totaliMeTVSH = 0;
        double zbritje = 0;
        double tvshtotal = 0;

private void ReportHeader_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
xrPictureBox1.Image = AlphaWebReports.raporteUtil.MerrLogoNdermarrje(this.Extensions["ndermarrjeLogo"]);

}

private void xrTableCell1_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
            totaliMeTVSH += Convert.ToDouble(GetCurrentColumnValue("VLEFTAMETVSH"));
            totaliPaTVSH += Convert.ToDouble(GetCurrentColumnValue("VLEFTAPATVSH"));
            zbritje = Convert.ToDouble(GetCurrentColumnValue("ZBRITJE"));
            tvshtotal = Convert.ToDouble(GetCurrentColumnValue("TVSHTOTAL"));
}

	//zbritja ne perqindje
private void xrTableCell42_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
            if (zbritje == null)
                xrTableCell42.Text = "0.00";
            else
            {
                if (totaliMeTVSH == 0)
                {
                    xrTableCell42.Text = "0.00";
                }
                else
                    xrTableCell42.Text = String.Format("{0:n2}", Math.Round((zbritje / totaliMeTVSH) * 100, 2));
            }
}

	//zbritja e pjeses pa tvsh
private void xrTableCell46_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
            if (zbritje == null || totaliMeTVSH==0)
                xrTableCell46.Text = "0.00";
            else
            xrTableCell46.Text = String.Format("{0:n2}",Math.Round((zbritje / totaliMeTVSH) * totaliPaTVSH, 2));
}

        //zbritja e tvsh-se
private void xrTableCell49_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
            if (zbritje == null || totaliMeTVSH == 0 || (1 - (zbritje / totaliMeTVSH))==0)
                xrTableCell49.Text = "0.00";
            else
            {
                double onePercent = tvshtotal / ((1 - (zbritje / totaliMeTVSH)) * 100);
                xrTableCell49.Text = String.Format("{0:n2}", Math.Round((zbritje / totaliMeTVSH) * 100 * onePercent, 2));
            }
}

        //zbritja totale
private void xrTableCell50_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
            if (zbritje == null || totaliMeTVSH == 0)
                xrTableCell50.Text = "0.00";
            else
            xrTableCell50.Text = String.Format("{0:n2}", Math.Round((zbritje / totaliMeTVSH) * totaliMeTVSH, 2));
}

        //totali pa tvsh me zbritje
private void xrTableCell58_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
            if (zbritje == null || totaliMeTVSH == 0)
                xrTableCell58.Text = "0.00";
            else
            {
                double value = Math.Round(totaliPaTVSH - (zbritje / totaliMeTVSH) * totaliPaTVSH, 2);
                xrTableCell58.Text = String.Format("{0:n2}", value);
            }
}

        //tvsh-ja me zbritje
private void xrTableCell59_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
            xrTableCell59.Text = String.Format("{0:n2}", Math.Round(tvshtotal, 2));
}

        //totali me tvsh me zbritje
private void xrTableCell60_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
            if (zbritje == null || totaliMeTVSH == 0)
                xrTableCell60.Text = "0.00";
            else
            {
                double value = Math.Round(totaliMeTVSH - (zbritje / totaliMeTVSH) * totaliMeTVSH, 2);
                xrTableCell60.Text = String.Format("{0:n2}", value);
            }
}

private void xrTableCell43_SummaryGetResult(object sender, DevExpress.XtraReports.UI.SummaryGetResultEventArgs e) {
            furnizimeTeTatueshme = totalVleftaPaTvshPerArtMeTvsh * (1 - (Convert.ToDouble(GetCurrentColumnValue("ZBRITJE")) / Convert.ToDouble(GetCurrentColumnValue("TOTALI"))));
            e.Result = Math.Round(furnizimeTeTatueshme, 2);
            e.Handled = true;
}

private void xrTableCell43_SummaryReset(object sender, System.EventArgs e) {
            furnizimeTeTatueshme = 0;
}

private void xrTableCell43_SummaryRowChanged(object sender, System.EventArgs e) {
            furnizimeTeTatueshme = totalVleftaPaTvshPerArtMeTvsh * (1 - (Convert.ToDouble(GetCurrentColumnValue("ZBRITJE")) / Convert.ToDouble(GetCurrentColumnValue("TOTALI"))));
}

private void xrTableCell34_SummaryGetResult(object sender, DevExpress.XtraReports.UI.SummaryGetResultEventArgs e) {
            furnizimeTePaTatueshme = totalVleftaPaTvshPerArtPaTvsh * (1 - (Convert.ToDouble(GetCurrentColumnValue("ZBRITJE")) / Convert.ToDouble(GetCurrentColumnValue("TOTALI"))));
            e.Result = Math.Round(furnizimeTePaTatueshme, 2);
            e.Handled = true;
}

private void xrTableCell34_SummaryReset(object sender, System.EventArgs e) {
            furnizimeTeTatueshme = 0;
}

private void xrTableCell34_SummaryRowChanged(object sender, System.EventArgs e) {
            furnizimeTeTatueshme = totalVleftaPaTvshPerArtMeTvsh * (1 - (Convert.ToDouble(GetCurrentColumnValue("ZBRITJE")) / Convert.ToDouble(GetCurrentColumnValue("TOTALI"))));
}

private void xrTableCell16_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
            if (GetCurrentColumnValue("tvsh").ToString() != "" && Convert.ToDouble(GetCurrentColumnValue("tvsh")) != 0)
                totalVleftaPaTvshPerArtMeTvsh += Convert.ToDouble(GetCurrentColumnValue("VLEFTAPATVSH"));
            else
                totalVleftaPaTvshPerArtPaTvsh += Convert.ToDouble(GetCurrentColumnValue("VLEFTAPATVSH"));
}

private void xrLabel6_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
            xrLabel6.Text = GetCurrentColumnValue("EMRIAGJENTSHITJE").ToString() + " " + GetCurrentColumnValue("MBIEMRIAGJENTSHITJE").ToString();
}
